#!/usr/bin/env python3
"""Compact Arrange + Frame/Asset controls for Design 2.0 Inspector."""

def install(html):
    css=r'''<style id="d2-arrange-css">#d2-arrange,#d2-assets{margin-top:12px}.d2-arrange-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:4px}.d2-arrange-grid button,.d2-group-actions button,.d2-arrange-wide button,.d2-asset-actions button{margin:0!important;padding:6px 4px!important;font:9px Inter,sans-serif!important}.d2-group-actions,.d2-arrange-wide,.d2-asset-actions{display:grid;grid-template-columns:1fr 1fr;gap:4px;margin-top:5px}.d2-group-readout{margin:6px 0;color:#8b8579;font:9px ui-monospace,monospace}.d2-gap{display:grid;grid-template-columns:1fr 54px;gap:5px;margin-top:5px}.d2-gap input,.d2-asset-row input,.d2-asset-row select{width:100%;box-sizing:border-box;border:1px solid #d9d3c7;background:#fbfaf6;padding:6px;font:9px ui-monospace,monospace}.d2-asset-row{display:grid;grid-template-columns:1fr 1fr;gap:5px;margin-top:5px}#d2-image-file{display:none}.d2-asset-note{margin-top:5px;color:#8b8579;font:9px/1.4 Inter,sans-serif}</style>'''
    panel=r'''<div id="d2-arrange"><div class="d2-section-title">ARRANGE</div><div id="d2-selection-readout" class="d2-group-readout">1 selected</div><div class="d2-arrange-grid"><button data-align="left">Left</button><button data-align="center">Center</button><button data-align="right">Right</button><button data-align="top">Top</button><button data-align="middle">Middle</button><button data-align="bottom">Bottom</button></div><div class="d2-arrange-wide"><button data-center="canvas-x">Center canvas ↔</button><button data-center="canvas-y">Center canvas ↕</button></div><div class="d2-arrange-wide"><button data-distribute="horizontal">Distribute ↔</button><button data-distribute="vertical">Distribute ↕</button></div><div class="d2-gap"><input id="d2-gap" type="number" min="0" value="24"><div class="d2-arrange-wide" style="margin:0"><button data-stack="horizontal">Gap ↔</button><button data-stack="vertical">Gap ↕</button></div></div><div class="d2-arrange-wide"><button data-z="front">Bring front</button><button data-z="forward">Forward</button><button data-z="backward">Backward</button><button data-z="back">Send back</button></div><div class="d2-group-actions"><button id="d2-group">Group</button><button id="d2-ungroup">Ungroup</button></div></div><div id="d2-assets"><div class="d2-section-title">FRAME · ASSET</div><div class="d2-asset-actions"><button id="d2-add-frame">+ Frame</button><button id="d2-add-image">+ Image</button></div><input id="d2-image-file" type="file" accept="image/png,image/jpeg,image/webp,image/gif,image/svg+xml"><div class="d2-asset-row"><select id="d2-fit"><option value="cover">Cover</option><option value="contain">Contain</option><option value="fill">Fill</option></select><button id="d2-fit-apply">Apply fit</button></div><div class="d2-asset-row"><input id="d2-crop-x" type="number" min="0" max="100" value="50"><input id="d2-crop-y" type="number" min="0" max="100" value="50"></div><div class="d2-asset-actions"><button id="d2-crop-apply">Apply position</button><button id="d2-replace-image">Replace image</button></div><div id="d2-asset-note" class="d2-asset-note">Images stay local in the structured workspace.</div></div>'''
    js=r'''<script id="d2-arrange-js">(()=>{const g=id=>document.getElementById(id);let ids=[],replaceMode=false;function page(){return ws?.pages?.find(x=>x.id===active)}function node(){return page()?.nodes?.find(n=>n.id===selected?.id)}function currentIds(){return ids.length?ids:(selected?.id?[selected.id]:[])}async function post(payload){const r=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok){g('status').textContent='DESIGN UPDATE FAILED';return null}ws=await r.json();g('status').textContent='saved · r'+ws.revision+' · '+active;return ws}function send(op,extra={}){const list=currentIds();if(list.length)g('canvas').contentWindow.postMessage({type:'d2-canvas-command',page_id:active,op,ids:list,...extra},'*')}async function zorder(mode){const list=currentIds(),p=page();if(!list.length||!p)return;let arr=p.nodes.map(n=>n.id),chosen=arr.filter(id=>list.includes(id));if(mode==='front')arr=arr.filter(id=>!list.includes(id)).concat(chosen);else if(mode==='back')arr=chosen.concat(arr.filter(id=>!list.includes(id)));else for(const id of (mode==='forward'?[...chosen].reverse():chosen)){let i=arr.indexOf(id),j=mode==='forward'?Math.min(arr.length-1,i+1):Math.max(0,i-1);if(i!==j)[arr[i],arr[j]]=[arr[j],arr[i]]}await post({op:'reorder_nodes',page_id:active,order:arr});g('canvas').src=canvasUrl();renderLayers()}function syncAsset(){const n=node(),image=n?.type==='image';['d2-fit','d2-fit-apply','d2-crop-x','d2-crop-y','d2-crop-apply','d2-replace-image'].forEach(id=>g(id).disabled=!image);if(image){g('d2-fit').value=n.fit||'cover';g('d2-crop-x').value=n.crop_x??50;g('d2-crop-y').value=n.crop_y??50;g('d2-asset-note').textContent='Image · '+(n.asset_id||'asset')}else g('d2-asset-note').textContent='Images stay local in the structured workspace.'}async function addFrame(){await post({op:'add_frame',page_id:active,x:120,y:180,w:960,h:540});g('canvas').src=canvasUrl();renderLayers()}function chooseImage(replace=false){replaceMode=replace;g('d2-image-file').value='';g('d2-image-file').click()}g('d2-image-file').onchange=e=>{const f=e.target.files?.[0];if(!f||f.size>8*1024*1024){g('status').textContent='IMAGE MUST BE ≤ 8 MB';return}const reader=new FileReader();reader.onload=async()=>{const uri=reader.result,n=node();if(replaceMode&&n?.type==='image'&&n.asset_id)await post({op:'set_asset',page_id:active,asset_id:n.asset_id,patch:{uri,name:f.name,mime:f.type}});else{const stamp=Date.now().toString(36),aid='asset-'+stamp,nid='image-'+stamp;await post({op:'place_image',page_id:active,asset:{id:aid,kind:'image',uri,name:f.name,mime:f.type},shape:{id:nid,type:'image',asset_id:aid,x:120,y:220,w:960,h:540,fit:'cover',crop_x:50,crop_y:50}})}g('canvas').src=canvasUrl();renderLayers();syncAsset()};reader.readAsDataURL(f)};document.querySelectorAll('[data-align]').forEach(b=>b.onclick=()=>send('align_nodes',{mode:b.dataset.align}));document.querySelectorAll('[data-center]').forEach(b=>b.onclick=()=>send('center_nodes',{mode:b.dataset.center,canvas_w:1200,canvas_h:2280}));document.querySelectorAll('[data-distribute]').forEach(b=>b.onclick=()=>send('distribute_nodes',{mode:b.dataset.distribute}));document.querySelectorAll('[data-stack]').forEach(b=>b.onclick=()=>send('stack_nodes',{mode:b.dataset.stack,gap:+g('d2-gap').value||0}));document.querySelectorAll('[data-z]').forEach(b=>b.onclick=()=>zorder(b.dataset.z));g('d2-group').onclick=()=>send('group_nodes',{group_id:'group-'+Date.now().toString(36)});g('d2-ungroup').onclick=()=>send('ungroup_nodes');g('d2-add-frame').onclick=addFrame;g('d2-add-image').onclick=()=>chooseImage();g('d2-replace-image').onclick=()=>chooseImage(true);g('d2-fit-apply').onclick=async()=>{const n=node();if(n?.type==='image'){await post({op:'set_node',page_id:active,id:n.id,patch:{fit:g('d2-fit').value}});g('canvas').src=canvasUrl()}};g('d2-crop-apply').onclick=async()=>{const n=node();if(n?.type==='image'){await post({op:'set_node',page_id:active,id:n.id,patch:{crop_x:Math.max(0,Math.min(100,+g('d2-crop-x').value||0)),crop_y:Math.max(0,Math.min(100,+g('d2-crop-y').value||0))}});g('canvas').src=canvasUrl()}};window.addEventListener('message',e=>{const m=e.data||{};if(m.type==='dore-selection-set'&&m.page_id===active){ids=m.ids||[];g('d2-selection-readout').textContent=ids.length+' selected';setTimeout(syncAsset,0)}});const oldSelect=select;select=function(id,field,value,el){oldSelect(id,field,value,el);if(!ids.includes(id))ids=[id];g('d2-selection-readout').textContent=ids.length+' selected';syncAsset()};setTimeout(syncAsset,80)})()</script>'''
    return html.replace('</head>',css+'</head>',1).replace('</div><p class="hint">Homepage and Journal are separate workspace pages.','</div>'+panel+'<p class="hint">Homepage and Journal are separate workspace pages.',1).replace('</body>',js+'</body>',1)
